static void fail(const std::string&s){throw std::runtime_error("test_model_package: "+s);}
struct E{std::string file;std::vector<int64_t> shape;};
static std::map<std::string,E> mf(const fs::path&p){std::ifstream in(p);if(!in)fail("missing golden manifest");std::map<std::string,E>r;std::string n,f;int rank;while(in>>n>>f>>rank){E e{f,{}};for(int i=0;i<rank;++i){int64_t d;if(!(in>>d))fail("bad manifest");e.shape.push_back(d);}r[n]=e;}return r;}
static Tensor file(const fs::path&d,const std::map<std::string,E>&m,const std::string&n){auto i=m.find(n);if(i==m.end())fail("golden node missing "+n);std::ifstream in(d/i->second.file,std::ios::binary|std::ios::ate);if(!in)fail("golden file missing "+n);auto sz=static_cast<size_t>(in.tellg());size_t num=1;for(auto x:i->second.shape)num*=size_t(x);if(sz!=num*4)fail("golden byte size "+n);in.seekg(0);std::vector<float>v(num);in.read(reinterpret_cast<char*>(v.data()),sz);return Tensor::from_f32(i->second.shape,v);}
static double cos(const Tensor&a,const Tensor&b){double ab=0,aa=0,bb=0;for(size_t i=0;i<a.numel();++i){double x=a.get_f32(i),y=b.get_f32(i);ab+=x*y;aa+=x*x;bb+=y*y;}return aa&&bb?ab/std::sqrt(aa*bb):aa==bb?1:0;}
static void cmp(const std::string&n,const Tensor&a,const Tensor&b){if(a.shape()!=b.shape())fail(n+" shape mismatch");float mx=0;double mean=0;for(size_t i=0;i<a.numel();++i){float d=std::fabs(a.get_f32(i)-b.get_f32(i));mx=std::max(mx,d);mean+=d;}mean/=a.numel();double c=cos(a,b);std::cout<<n<<" shape=";for(auto d:a.shape())std::cout<<d<<"x";std::cout<<" max_abs_error="<<mx<<" mean_abs_error="<<mean<<" cosine_similarity="<<c<<"\n";if(mx>5e-4||c<.99999)fail(n+" threshold max_error="+std::to_string(mx)+" cosine_similarity="+std::to_string(c));}
static Tensor z(std::vector<int64_t>s){size_t n=1;for(auto d:s)n*=size_t(d);return Tensor::from_f32(s,std::vector<float>(n));}
static double package_positive(const ModelPackage&p,const std::string&key){const std::string v=p.config(key);size_t pos=0;double x;try{x=std::stod(v,&pos);}catch(...){fail("config "+key+" is not a valid number: "+v);}if(pos!=v.size()||!std::isfinite(x)||x<=0)fail("config "+key+" invalid actual="+v);return x;}
