 ModelPackage p(pkg);if(p.resolve_name("lm_head")!="token_embedding")fail("lm_head alias does not resolve to token_embedding");if(p.tensors().size()!=310||p.aliases().size()!=1)fail("unexpected physical tensor/alias count");std::map<std::string,bool> present;for(auto&t:p.tensors())present[t.name]=true;for(int i=0;i<28;++i)for(auto n:{"input_norm","q_proj","k_proj","v_proj","q_norm","k_norm","o_proj","post_attention_norm","gate_proj","up_proj","down_proj"})if(!present["layers."+std::to_string(i)+"."+n])fail("missing layer weight");
 auto gm=mf(gold/"manifest.txt");auto h=file(gold,gm,"hidden_states"),pos=file(gold,gm,"position_ids");std::vector<int32_t> ids(pos.numel());for(size_t i=0;i<ids.size();++i)ids[i]=int32_t(pos.get_f32(i));double eps=package_positive(p,"rms_norm_eps"),theta=package_positive(p,"rope_theta");std::cout<<"rms_norm_eps="<<eps<<" rope_theta="<<theta<<"\n";Qwen3LayerWeights w{p.load_tensor("layers.0.input_norm"),p.load_tensor("layers.0.q_proj"),p.load_tensor("layers.0.k_proj"),p.load_tensor("layers.0.v_proj"),p.load_tensor("layers.0.q_norm"),p.load_tensor("layers.0.k_norm"),p.load_tensor("layers.0.o_proj"),p.load_tensor("layers.0.post_attention_norm"),p.load_tensor("layers.0.gate_proj"),p.load_tensor("layers.0.up_proj"),p.load_tensor("layers.0.down_proj")};auto r=qwen3_decoder_layer_trace(h,ids,w,float(eps),float(theta));for(auto&x:std::map<std::string,const Tensor*>{{"q_linear",&r.q_linear},{"q_rope",&r.q_rope},{"attention_output",&r.attention_output},{"swiglu_output",&r.swiglu_output},{"layer_output",&r.layer_output}})cmp(x.first,*x.second,file(gold,gm,x.first));
